INSERT INTO public.clues (slug, clue_text, answer, source, explanation, appearances) VALUES
('capital-of-france', 'Capital of France', 'PARIS', 'nyt-mini', 'Paris takes its name from the Parisii, a Celtic tribe that settled on the Seine long before the Romans arrived. As a five-letter answer packed with common letters, it is a crossword staple, often clued through the Eiffel Tower, the Louvre, or French geography.', 2),
('opposite-of-night', 'Opposite of night', 'DAY', 'nyt-mini', 'Day traces back to the Old English "dæg," and it has referred to both the daylight hours and the full 24-hour cycle for over a thousand years. Its brevity and vowel-consonant balance make it one of the most frequently used three-letter fills in puzzles.', 1),
('mac-and-cheese', '___ and cheese', 'MAC', 'nyt-mini', 'Mac is short for macaroni, itself borrowed from the Italian "maccheroni." The word does double duty in crosswords, cluing the comfort food, a raincoat, an Apple computer, or the informal address "hey, Mac."', 2),
('father-informally', 'Father, informally', 'DAD', 'nyt-mini', 'Dad is thought to imitate a baby''s earliest babbling sounds, which is why similar words appear across unrelated languages. Being a short palindrome loaded with the common letters D and A, it is a favorite crossword filler.', 1),
('ocean-motion', 'Ocean motion', 'WAVE', 'nyt-mini', 'Wave comes from the Old English "wafian," meaning to move the hands to and fro, and later expanded to water swells and physics phenomena like sound and light. Its many meanings, from a hand gesture to a stadium ritual, give clue writers plenty of playful options.', 3),
('nocturnal-bird', 'Nocturnal bird', 'OWL', 'nyt-mini', 'Owl derives from the Old English "ule," an imitation of the bird''s hooting call. Rich in vowels and rounded out by a single L, it slots neatly into tight corners and often signals wisdom or a person who stays up late.', 1),
('frozen-water', 'Frozen water', 'ICE', 'nyt-mini', 'Ice comes from the Old English "is" and shares roots across Germanic languages. Two vowels bracketing a C make it a workhorse fill, clued through hockey, cocktails, glaciers, or slang for diamonds.', 2),
('shade-tree', 'Shade tree', 'ELM', 'nyt-mini', 'Elm is an ancient tree name that has stayed nearly unchanged from Old English to today. Its unusual consonant cluster of L and M makes it invaluable for filling awkward grid spots, and it often nods to tree-lined streets or the horror film franchise.', 1),
('afternoon-drink', 'Afternoon drink', 'TEA', 'nyt-mini', 'Tea entered English through the Dutch "thee," ultimately from a Chinese dialect word for the plant. With two vowels and a soft T, it is a crossword favorite that can also mean gossip in modern slang.', 2),
('tennis-serve-winner', 'Tennis serve winner', 'ACE', 'nyt-mini', 'Ace comes from the Latin "as," a single unit or the lowest coin, and evolved to mean the number-one card and, later, anything excellent. Its vowel-heavy shape and multiple meanings, from pilots to unreturnable serves, make it endlessly reusable.', 1),
('freudian-self', 'Freudian self', 'EGO', 'nyt-mini', 'Ego is simply the Latin word for "I," adopted by Sigmund Freud to name the part of the psyche that mediates between desire and reality. Loaded with the common letters E, G, and O, it frequently appears alongside clues about pride or psychology.', 2),
('repeated-sound', 'Repeated sound', 'ECHO', 'nyt-mini', 'Echo comes from a Greek nymph in mythology who could only repeat the last words spoken to her. The tidy alternation of vowels and consonants keeps it in heavy rotation, now also cluing Amazon''s smart speaker.', 1),
('red-planet', 'Red Planet', 'MARS', 'nyt-mini', 'Mars is named for the Roman god of war, a nod to its blood-red hue caused by iron oxide dust. As a four-letter answer it does triple duty in puzzles, cluing the planet, the deity, or the candy company.', 2),
('breakfast-grain', 'Breakfast grain', 'OATS', 'nyt-mini', 'Oats descend from the Old English "ate," a cereal grain long prized for both livestock feed and porridge. The plural''s friendly letters make it a common crossword entry, sometimes hinting at "sowing wild oats."', 1),
('part-of-the-eye', 'Part of the eye', 'IRIS', 'nyt-mini', 'Iris means "rainbow" in Greek and was the name of a messenger goddess, which is why it labels both the colored ring of the eye and a vividly hued flower. Its symmetry and vowels make it a versatile grid filler.', 2),
('longest-river', 'Longest river', 'NILE', 'nyt-mini', 'The Nile takes its name from the Greek "Neilos," and it has anchored Egyptian civilization for millennia. Compact and vowel-rich, it is a go-to geography answer often paired with clues about pyramids or Cleopatra.', 1),
('green-gemstone', 'Green gemstone', 'JADE', 'nyt-mini', 'Jade comes from the Spanish "piedra de ijada," or "stone of the flank," once believed to cure kidney ailments. Its useful J gives constructors a crossing option, and it doubles as a popular given name.', 2),
('water-in-latin', 'Water, in Latin', 'AQUA', 'nyt-mini', 'Aqua is the Latin word for water and the root of terms like aquarium and aqueduct. Its trio of A''s makes it a lifesaver in vowel-starved corners, and it also names a blue-green color.', 1),
('bright-sign-gas', 'Bright sign gas', 'NEON', 'nyt-mini', 'Neon is derived from the Greek "neos," meaning new, since it was a newly discovered noble gas in 1898. Its glowing signs and palindrome-adjacent spelling make it a favorite for cluing both chemistry and vivid colors.', 2),
('volcano-output', 'Volcano output', 'LAVA', 'nyt-mini', 'Lava comes from the Italian dialect word for a stream, originally describing rainwater runoff before naming molten rock. Two A''s and light consonants make it easy to cross, and it also evokes lamps and soap.', 1),
('vast-body-of-water', 'Vast body of water', 'OCEAN', 'nyt-mini', 'Ocean stems from the Greek "Okeanos," a titan who personified the great river believed to encircle the world. Its balanced vowels and consonants make it a common five-letter answer for geography and nature themes.', 1),
('sour-citrus-fruit', 'Sour citrus fruit', 'LEMON', 'nyt-mini', 'Lemon likely arrived in English through Arabic and Persian roots for citrus. Beyond the fruit, it colorfully labels a defective car, giving clue writers a chance for misdirection.', 2),
('batmans-sidekick', 'Batman''s sidekick', 'ROBIN', 'nyt-mini', 'Robin doubles as the name of a cheerful red-breasted bird and the Boy Wonder of Gotham City. Its common letters and dual meaning make it a flexible five-letter fill, sometimes nodding to Sherwood Forest.', 1),
('striped-big-cat', 'Striped big cat', 'TIGER', 'nyt-mini', 'Tiger traces through Latin and Greek back to a Persian word meaning arrow, a nod to the animal''s speed. The word crosses cleanly and often hints at golf legend Tiger Woods or a fierce competitor.', 2),
('keyboard-instrument', 'Keyboard instrument', 'PIANO', 'nyt-mini', 'Piano is short for "pianoforte," Italian for "soft-loud," describing the instrument''s dynamic range. It also serves as a musical direction meaning quiet, giving puzzles two angles for the same answer.', 1),
('flowing-waterway', 'Flowing waterway', 'RIVER', 'nyt-mini', 'River comes from the Latin "riparia," relating to a bank or shore. Its everyday familiarity and friendly letters make it a reliable five-letter entry across geography and nature grids.', 1),
('tropical-fruit', 'Tropical fruit', 'MANGO', 'nyt-mini', 'Mango reached English through Portuguese from the Tamil word "mankay." Its punchy G and rounded O make it a colorful five-letter answer for food-themed puzzles.', 2),
('halloween-figure', 'Halloween figure', 'GHOST', 'nyt-mini', 'Ghost descends from the Old English "gast," meaning spirit or breath; the silent H was added later under Flemish influence. Its spooky connotations and modern dating slang keep it lively for clue writers.', 1),
('national-bird-of-the-us', 'National bird of the US', 'EAGLE', 'nyt-mini', 'Eagle comes from the Latin "aquila" by way of Old French. Beyond the bald eagle emblem, it names a golf score of two under par, offering a sporty misdirection.', 2),
('capital-of-england', 'Capital of England', 'LONDON', 'nyt-mini', 'London''s name likely predates the Romans, who called their settlement Londinium. As a six-letter geography answer it appears often, clued through the Thames, Big Ben, or Jack London.', 2),
('earth-eg', 'Earth, e.g.', 'PLANET', 'nyt-mini', 'Planet comes from the Greek "planetes," meaning wanderer, since these bodies appeared to drift against the fixed stars. Its steady mix of letters makes it a dependable six-letter fill for science themes.', 1),
('citrus-and-color', 'Citrus and color', 'ORANGE', 'nyt-mini', 'Orange named the fruit first, arriving from Sanskrit through Persian and Arabic; only later did English apply it to the color. Famously hard to rhyme, it is a satisfying six-letter answer.', 2),
('pungent-bulb', 'Pungent bulb', 'GARLIC', 'nyt-mini', 'Garlic comes from the Old English "garleac," combining "gar" (spear) and "leac" (leek), a nod to its spear-shaped leaves. Its distinctive letters make it a flavorful six-letter kitchen answer.', 1),
('precious-metal', 'Precious metal', 'SILVER', 'nyt-mini', 'Silver descends from the Old English "seolfor" and lends its name to the element symbol Ag from Latin "argentum." It also means a second-place medal and the Lone Ranger''s horse, giving constructors options.', 1),
('woodland-area', 'Woodland area', 'FOREST', 'nyt-mini', 'Forest comes from the Latin "forestis silva," meaning the outside woods reserved for royal hunting. Its common letters and vivid imagery make it a natural six-letter entry, sometimes cluing Forrest Gump.', 2),
('arid-region', 'Arid region', 'DESERT', 'nyt-mini', 'Desert derives from the Latin "desertum," meaning an abandoned place. Its spelling collides usefully with "dessert" and the verb meaning to abandon, so clue writers enjoy the ambiguity.', 1),
('shelled-reptile', 'Shelled reptile', 'TURTLE', 'nyt-mini', 'Turtle likely comes from the French "tortue," possibly influenced by "turtledove." A friendly six-letter answer, it evokes slow-and-steady fables and the Teenage Mutant Ninja heroes.', 2),
('night-sky-orb', 'Night sky orb', 'MOON', 'nyt-mini', 'Moon shares an ancient root with "month," since early calendars tracked its cycles. The double O makes it a smooth four-letter fill, often clued through phases, tides, or the Apollo landings.', 1),
('twinkling-light', 'Twinkling light', 'STAR', 'nyt-mini', 'Star comes from the Old English "steorra" and connects to a broad family of Indo-European words. It doubles as slang for a celebrity, letting clue writers pivot between astronomy and Hollywood.', 2),
('wet-weather', 'Wet weather', 'RAIN', 'nyt-mini', 'Rain stems from the Old English "regn" and is shared across the Germanic languages. Homophones like "reign" and "rein" give constructors rich wordplay for this common four-letter answer.', 1),
('winter-precipitation', 'Winter precipitation', 'SNOW', 'nyt-mini', 'Snow descends from the Old English "snaw" and has an ancient shared root across Europe. Its clean consonants and W ending make it a handy four-letter answer for seasonal or nature clues.', 1),
('valentines-flower', 'Valentine''s flower', 'ROSE', 'nyt-mini', 'Rose comes from the Latin "rosa" and is one of the oldest cultivated flowers. It cleverly doubles as the past tense of "rise" and a popular name, so it appears constantly in mini puzzles.', 2),
('keeps-the-doctor-away', 'Keeps the doctor away, in a saying', 'APPLE', 'nyt-mini', 'Apple traces to the Old English "æppel," which once meant any fruit before narrowing to the familiar orchard fruit. Its everyday letters and tech-company double meaning make it a versatile five-letter fill.', 2),
('vineyard-fruit', 'Vineyard fruit', 'GRAPE', 'nyt-mini', 'Grape comes from the Old French "grape," originally referring to a hook used to harvest clusters. Its crisp consonants make it a satisfying five-letter answer, sometimes cluing the color or the vine.', 1),
('striped-african-animal', 'Striped African animal', 'ZEBRA', 'nyt-mini', 'Zebra likely came into English via Portuguese, possibly from an African language or a Latin word for a wild horse. Its rare Z makes it a prized crossing letter for constructors.', 2),
('icy-space-traveler', 'Icy space traveler', 'COMET', 'nyt-mini', 'Comet derives from the Greek "kometes," meaning long-haired, describing the glowing tail. Its common letters make it an easy five-letter fill, and it is also one of Santa''s reindeer.', 1),
('picnic-pest', 'Picnic pest', 'ANT', 'nyt-mini', 'Ant comes from the Old English "æmete," the same root that eventually gave us "emmet." Compact and vowel-friendly, it is one of the most common three-letter answers, often paired with picnic or colony clues.', 1),
('sly-animal', 'Sly animal', 'FOX', 'nyt-mini', 'Fox descends from the Old English "fox" and has long symbolized cunning in fables. Its rare X makes it a valuable crossing letter, and it also names a major television network.', 2),
('star-at-center-of-solar-system', 'Star at the center of the solar system', 'SUN', 'nyt-mini', 'Sun comes from the Old English "sunne" and anchors our word for Sunday. A tidy three-letter answer, it invites homophone play with "son" and appears across science and weather clues.', 1),
('cold-season', 'Cold season', 'WINTER', 'nyt-mini', 'Winter descends from the Old English "winter" and shares a root possibly linked to "wet" or "white." A common six-letter answer, it also serves as a surname, as in soul singer Edgar Winter.', 2);
